const text = observation && typeof observation.text === "string" ? observation.text : String(observation?.text ?? "");
const trimmed = text.trim();

try {
  const value = JSON.parse(trimmed);
  if (value && typeof value === "object" && !Array.isArray(value) && Object.prototype.hasOwnProperty.call(value, "answer")) {
    return String(value.answer);
  }
} catch {}

const csv = trimmed.match(/^(?:id,answer\r?\n)?[^,\r\n]+,([^\r\n]+)$/i);
if (csv) return csv[1].trim();

const data = trimmed.match(/^DATA\s+answer=(.*)$/is);
if (data) return data[1].trim();

return text;

